#!/usr/bin/env bash
# Writes web/config.js from apps/android/supabase.properties, so the tracker
# and the app always talk to the same backend. Used by the Pages workflow and
# the pull-request check. The anon key is public by design.
set -euo pipefail
PROPS=apps/android/supabase.properties
URL=$(grep '^SUPABASE_URL=' "$PROPS" | cut -d= -f2- | tr -d ' \r')
KEY=$(grep '^SUPABASE_ANON_KEY=' "$PROPS" | cut -d= -f2- | tr -d ' \r')
cat > web/config.js <<CONFIG
/* Generated by tools/web/write-config.sh from apps/android/supabase.properties — do not edit by hand. */
window.KOODE_CONFIG = {
  SUPABASE_URL: "$URL",
  SUPABASE_ANON_KEY: "$KEY"
};
CONFIG
echo "Wrote web/config.js for $URL"
